    RAISE EXCEPTION 'Discord subject cannot be both claimed and permanently linked'
      USING ERRCODE = 'unique_violation', CONSTRAINT = 'iac_discord_claim_external_identity_conflict';
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql
